-- Entorno desechable de PostgreSQL: nunca ejecutar estos fixtures en Supabase.
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE ROLE sgi_backend_user;
CREATE ROLE sigi_app_user BYPASSRLS;
CREATE TABLE public.seg_usuarios(id_usuario bigint PRIMARY KEY);
CREATE TABLE public.inm_proyectos(id_proyecto bigint PRIMARY KEY,activo boolean NOT NULL DEFAULT true);
CREATE TABLE public.inm_etapas(id_etapa bigint PRIMARY KEY,activo boolean NOT NULL DEFAULT true);
CREATE TABLE public.inm_manzanas(id_manzana bigint PRIMARY KEY,id_etapa bigint REFERENCES public.inm_etapas,activo boolean NOT NULL DEFAULT true);
CREATE TABLE public.cfg_estados_lote(id_estado_lote integer PRIMARY KEY,codigo text,activo boolean DEFAULT true);
CREATE TABLE public.inm_lotes(id_lote bigint PRIMARY KEY,id_proyecto bigint REFERENCES public.inm_proyectos,id_manzana bigint REFERENCES public.inm_manzanas,id_estado_lote integer REFERENCES public.cfg_estados_lote,activo boolean DEFAULT true,UNIQUE(id_lote,id_proyecto));
CREATE TABLE public.cfg_monedas(id_moneda integer PRIMARY KEY,codigo text,activo boolean DEFAULT true);
CREATE TABLE public.inm_lotes_precios(id_lote_precio bigint PRIMARY KEY,id_lote bigint REFERENCES public.inm_lotes,id_moneda integer REFERENCES public.cfg_monedas,precio numeric(14,2),activo boolean DEFAULT true,fecha_desde timestamptz DEFAULT now(),fecha_hasta timestamptz);
CREATE TABLE public.cfg_estados_reserva(id_estado_reserva integer PRIMARY KEY,codigo text);
CREATE TABLE public.ven_reservas(id_reserva bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_lote bigint REFERENCES public.inm_lotes,id_moneda integer REFERENCES public.cfg_monedas,id_estado_reserva integer REFERENCES public.cfg_estados_reserva,fecha_vencimiento timestamptz DEFAULT now()+interval '1 day');
CREATE TABLE public.ven_ventas(id_venta bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_lote bigint REFERENCES public.inm_lotes,id_moneda integer REFERENCES public.cfg_monedas,id_reserva bigint REFERENCES public.ven_reservas,precio_lista numeric(14,2),descuento numeric(14,2),precio_venta numeric(14,2));
